 91	    /**
 92	     * Show the current status of the field.
 93	     * @param step Which iteration step it is.
 94	     * @param field The field whose status is to be displayed.
 95	     */
 96	    public void showStatus(int step, Field field)
 97	    {
 98	        if(!isVisible()) {
 99	            setVisible(true);
100	        }
101	        String time = "";
102	        if (simulator.isNight()) {
103	            time = " Night";
104	        }
105	        else {
106	            time = " Day";
107	        }
108	        
109	        stepLabel.setText(STEP_PREFIX + step + time);
110	        stats.reset();
111	
112	        fieldView.preparePaint();
113	
114	        for(int row = 0; row < field.getDepth(); row++) {
115	            for(int col = 0; col < field.getWidth(); col++) {
116	                Object thing = field.getObjectAt(row, col);
117	                // If there is something in the grid space, draw it with correct colour
118	                if(thing!= null) {
119	                    stats.incrementCount(thing.getClass());
120	                    fieldView.drawMark(col, row, getColor(thing.getClass()));
121	                    // Check whether it is an organism and if it is infected
122	                    if (thing instanceof Organism) {
123	                        Organism organism = (Organism) thing;
124	                        if (organism.isInfected()) {
125	                            fieldView.markDisease(col, row, Color.black);
126	                        }
127	                    }
128	                    else if (thing instanceof WaterSources) {
129	                        WaterSources water = (WaterSources) thing;
130	                        if (water.isInfected()) {
131	                            fieldView.markDisease(col, row, Color.black);
132	                        }
133	                    }
134	                }
135	                else {
136	                    fieldView.drawMark(col, row, EMPTY_COLOR);
137	                    fieldView.markDisease(col, row, EMPTY_COLOR);
138	                }
139	
140	            }
141	        }
142	        stats.countFinished();
143	
144	        population.setText(POPULATION_PREFIX + demographics.getPopulationDetails(field));
145	        fieldView.repaint();
146	    }
